1	//! Markdown adjustments for rendering harness replies.
2	
3	/// `markdown` with inline code spans turned into their plain, escaped text.
4	///
5	/// gpui-kit 0.6.1's `TextView` lays out any paragraph containing inline code
6	/// with a flow that re-wraps each measured piece inside its own box, so words
7	/// overlap. Paragraphs without inline code use its normal text layout, which
8	/// wraps correctly. Fenced code blocks are left alone. Remove this once
9	/// gpui-kit fixes the flow.
10	pub fn without_inline_code(markdown: &str) -> String {
11	    let mut result = String::with_capacity(markdown.len());
12	    let mut fence: Option<(char, usize)> = None;
13	
14	    for line in markdown.split_inclusive('\n') {
15	        let trimmed = line.trim_start_matches(' ');
16	        let indent = line.len() - trimmed.len();
17	        let marker = trimmed.chars().next().filter(|c| matches!(c, '`' | '~'));
18	        let run = marker.map_or(0, |marker| {
19	            trimmed.chars().take_while(|c| *c == marker).count()
20	        });
21	
22	        if let Some(marker) = marker
23	            && indent <= 3
24	            && run >= 3
25	        {
26	            match fence {
27	                None => fence = Some((marker, run)),
28	                Some((open, len))
29	                    if marker == open && run >= len && trimmed[run..].trim().is_empty() =>
30	                {
31	                    fence = None
32	                }
33	                Some(_) => {}
34	            }
35	            result.push_str(line);
36	        } else if fence.is_some() {
37	            result.push_str(line);
38	        } else {
39	            result.push_str(&strip_code_spans(line));
40	        }
41	    }
42	    result
43	}
