45	/// Replaces each code span in `line` with its content, escaping Markdown
46	/// punctuation so the text stays literal. Unclosed backticks are kept.
47	fn strip_code_spans(line: &str) -> String {
48	    let mut out = String::with_capacity(line.len());
49	    let mut rest = line;
50	    while let Some(start) = rest.find('`') {
51	        let ticks = rest[start..].bytes().take_while(|b| *b == b'`').count();
52	        let after = &rest[start + ticks..];
53	        match closing_run(after, ticks) {
54	            Some(end) => {
55	                out.push_str(&rest[..start]);
56	                let code = &after[..end];
57	                // One space padding each side is not part of the code.
58	                let code = if code.len() >= 2
59	                    && code.starts_with(' ')
60	                    && code.ends_with(' ')
61	                    && !code.trim().is_empty()
62	                {
63	                    &code[1..code.len() - 1]
64	                } else {
65	                    code
66	                };
67	                for c in code.chars() {
68	                    if c.is_ascii_punctuation() {
69	                        out.push('\\');
70	                    }
71	                    out.push(c);
72	                }
73	                rest = &after[end + ticks..];
74	            }
75	            None => {
76	                out.push_str(&rest[..start + ticks]);
77	                rest = after;
78	            }
79	        }
80	    }
81	    out.push_str(rest);
82	    out
83	}
