90	        if bytes[ix] == b'`' {
91	            let len = bytes[ix..].iter().take_while(|b| **b == b'`').count();
92	            if len == ticks {
93	                return Some(ix);
94	            }
95	            ix += len;
96	        } else {
97	            ix += 1;
98	        }
99	    }
100	    None
101	}
