240	/// The most telling argument of a tool call: a command whole, as it is laid
241	/// out across lines where it is shown, anything else on one line.
242	fn summarize(input: &Value) -> Option<String> {
243	    const KEYS: [&str; 7] = [
244	        "command",
245	        "file_path",
246	        "pattern",
247	        "path",
248	        "url",
249	        "query",
250	        "description",
251	    ];
252	    const MAX_CHARS: usize = 120;
253	
254	    let (key, value) = KEYS
255	        .iter()
256	        .find_map(|key| Some((*key, input.get(key)?.as_str()?)))?;
257	    if key == "command" {
258	        return Some(value.to_string());
259	    }
260	    let line = value.lines().next().unwrap_or_default();
261	    Some(if line.chars().count() > MAX_CHARS {
262	        format!("{}…", line.chars().take(MAX_CHARS).collect::<String>())
263	    } else {
264	        line.to_string()
265	    })
266	}
